import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

// plugins/waypoint/types/index.d.ts is generated by build.mjs from BandModel; this catches a stale build.
describe('published mod state contract', () => {
  const contract = () => readFileSync('plugins/waypoint/types/index.d.ts', 'utf8').replace(/\r\n/g, '\n');
  const body = (file: string, name: string) =>
    new RegExp(String.raw`^export type ${name} =([\s\S]*?);\r?\n(?![ \t}])`, 'm').exec(readFileSync(file, 'utf8'))?.[1]?.replace(/\r\n/g, '\n');

  it('WaypointBand matches BandModel in src/mod/model.ts', () => {
    const band = body('src/mod/model.ts', 'BandModel');
    expect(band).toBeDefined();
    expect(contract()).toContain(`export type WaypointBand =${band};\n`);
  });
  it('declares the band and hidden state, and no panel', () => {
    expect(contract()).toContain('waypoint: { band: WaypointBand; hidden: boolean; drawn: boolean | null };');
    expect(readFileSync('src/mod/state.d.ts', 'utf8')).toContain('waypoint: { band: WaypointBand; hidden: boolean; drawn: boolean | null };');
    expect(contract()).not.toContain('Panel');
  });
});

describe('published lens state contract', () => {
  const contract = () => readFileSync('plugins/lens/types/index.d.ts', 'utf8').replace(/\r\n/g, '\n');
  const body = (file: string, name: string) =>
    new RegExp(String.raw`^export type ${name} =([\s\S]*?);\r?\n(?![ \t}])`, 'm').exec(readFileSync(file, 'utf8'))?.[1]?.replace(/\r\n/g, '\n');
  it('LensPanel matches PanelModel in src/lens/model.ts', () => {
    const panel = body('src/lens/model.ts', 'PanelModel');
    expect(panel).toMatch(/pricesAsOf:[^\n]*\n  \} \| null;\n\}$/);
    expect(contract()).toContain(`export type LensPanel =${panel};\n`);
  });
  it('declares the panel and hidden state', () => {
    expect(contract()).toContain('lens: { panel: LensPanel | null; hidden: boolean };');
  });
});

// build.mjs's modelType guard, read from what it published: outside a one-line quote, a capitalized word in a contract
// is a type the file does not declare (it would not compile, or read as any under skipLibCheck).
describe('published contracts are self-contained', () => {
  const names = (file: string, name: string) => {
    const b = new RegExp(String.raw`^export type ${name} =([\s\S]*?);\r?\n(?![ \t}])`, 'm').exec(readFileSync(file, 'utf8'))?.[1];
    expect(b).toBeDefined();
    return b!.replace(/'[^'\n]*'/g, '').match(/\b[A-Z]\w*/g) ?? [];
  };
  it('WaypointBand and LensPanel name no other type', () => {
    expect(names('plugins/waypoint/types/index.d.ts', 'WaypointBand')).toEqual([]);
    expect(names('plugins/lens/types/index.d.ts', 'LensPanel')).toEqual([]);
  });
});
